#!/usr/bin/env bash
# Crea las etiquetas y los 20 issues del taller con GitHub CLI (https://cli.github.com).
# Requisitos: `gh auth login` hecho y estar dentro del repositorio clonado.
# IMPORTANTE: ejecútalo en un repositorio SIN issues previos, para que los números #1..#20
# coincidan con los tags @Issue-1 ... @Issue-20 de los .feature.
set -euo pipefail

for l in positivo negativo "HU-02" Acceso "Registro de mascotas" "Reserva de estadía" "Cancelación" "test-case"; do
  gh label create "$l" --force >/dev/null
done

crear() { # titulo | etiquetas | cuerpo
  gh issue create --title "$1" --label "$2" --body "$3"
}

crear "[TC-01] Inicio de sesión con credenciales válidas" "test-case,HU-02,Acceso,positivo" "$(printf '%b' '**Caso de prueba (TestCase)**\n\n- **Requisito:** HU02-ACC-CA1 (HU-02, Acceso)\n- **Tipo:** positivo\n- **Escenario automatizado:** `src/test/resources/features/acceso/inicio_sesion.feature`\n- **Tag para ejecutarlo:** `@Issue-1`\n\n**Resultado esperado:** Con dueno / huellitas123 el usuario entra y ve la página «Mis mascotas».')"
crear "[TC-02] Rechazo de credenciales incorrectas (usuario o contraseña)" "test-case,HU-02,Acceso,negativo" "$(printf '%b' '**Caso de prueba (TestCase)**\n\n- **Requisito:** HU02-ACC-CA2 (HU-02, Acceso)\n- **Tipo:** negativo\n- **Escenario automatizado:** `src/test/resources/features/acceso/inicio_sesion.feature`\n- **Tag para ejecutarlo:** `@Issue-2`\n\n**Resultado esperado:** Se muestra «Usuario o contraseña incorrectos» y no se entra.')"
crear "[TC-03] Registro de un perro con datos válidos" "test-case,HU-02,Registro de mascotas,positivo" "$(printf '%b' '**Caso de prueba (TestCase)**\n\n- **Requisito:** HU02-F1-CA1, HU02-F1-CA5 (HU-02, Registro de mascotas)\n- **Tipo:** positivo\n- **Escenario automatizado:** `src/test/resources/features/mascotas/registro_mascotas.feature`\n- **Tag para ejecutarlo:** `@Issue-3`\n\n**Resultado esperado:** Mensaje «Rocky fue registrado con tamaño Mediano» y la mascota aparece en la lista con sus datos.')"
crear "[TC-04] Registro rechazado sin vacunas al día" "test-case,HU-02,Registro de mascotas,negativo" "$(printf '%b' '**Caso de prueba (TestCase)**\n\n- **Requisito:** HU02-F1-CA2 (HU-02, Registro de mascotas)\n- **Tipo:** negativo\n- **Escenario automatizado:** `src/test/resources/features/mascotas/registro_mascotas.feature`\n- **Tag para ejecutarlo:** `@Issue-4`\n\n**Resultado esperado:** Mensaje «No podemos hospedar mascotas sin vacunas al día» y la lista queda vacía.')"
crear "[TC-05] Tamaño automático según el peso (valores límite 10, 10.5, 24.9, 25)" "test-case,HU-02,Registro de mascotas,positivo" "$(printf '%b' '**Caso de prueba (TestCase)**\n\n- **Requisito:** HU02-F1-CA3 (HU-02, Registro de mascotas)\n- **Tipo:** positivo\n- **Escenario automatizado:** `src/test/resources/features/mascotas/registro_mascotas.feature`\n- **Tag para ejecutarlo:** `@Issue-5`\n\n**Resultado esperado:** Pequeño / Mediano / Mediano / Grande.')"
crear "[TC-06] Rechazo de datos inválidos (peso 0 y 80.1, edad 26, nombre de 1 y 31 caracteres)" "test-case,HU-02,Registro de mascotas,negativo" "$(printf '%b' '**Caso de prueba (TestCase)**\n\n- **Requisito:** HU02-F1-CA1 (HU-02, Registro de mascotas)\n- **Tipo:** negativo\n- **Escenario automatizado:** `src/test/resources/features/mascotas/registro_mascotas.feature`\n- **Tag para ejecutarlo:** `@Issue-6`\n\n**Resultado esperado:** Error de campo con el mensaje correspondiente.')"
crear "[TC-07] Nombre duplicado sin distinguir mayúsculas" "test-case,HU-02,Registro de mascotas,negativo" "$(printf '%b' '**Caso de prueba (TestCase)**\n\n- **Requisito:** HU02-F1-CA4 (HU-02, Registro de mascotas)\n- **Tipo:** negativo\n- **Escenario automatizado:** `src/test/resources/features/mascotas/registro_mascotas.feature`\n- **Tag para ejecutarlo:** `@Issue-7`\n\n**Resultado esperado:** Error «Ya existe una mascota registrada con ese nombre».')"
crear "[TC-08] Reserva con resumen y confirmación" "test-case,HU-02,Reserva de estadía,positivo" "$(printf '%b' '**Caso de prueba (TestCase)**\n\n- **Requisito:** HU02-F2-CA8, HU02-F2-CA10, HU02-F3-CA1 (HU-02, Reserva de estadía)\n- **Tipo:** positivo\n- **Escenario automatizado:** `src/test/resources/features/reservas/reserva_estadia.feature`\n- **Tag para ejecutarlo:** `@Issue-8`\n\n**Resultado esperado:** Total $110.000, código PS-XXXX y la reserva aparece «Confirmada» en Mis reservas.')"
crear "[TC-09] Total con baño y peluquería y paseo diario (perro)" "test-case,HU-02,Reserva de estadía,positivo" "$(printf '%b' '**Caso de prueba (TestCase)**\n\n- **Requisito:** HU02-F2-CA6 (HU-02, Reserva de estadía)\n- **Tipo:** positivo\n- **Escenario automatizado:** `src/test/resources/features/reservas/reserva_estadia.feature`\n- **Tag para ejecutarlo:** `@Issue-9`\n\n**Resultado esperado:** 3 noches de un perro mediano + baño + paseo = $220.000.')"
crear "[TC-10] Paseo diario no disponible para gatos" "test-case,HU-02,Reserva de estadía,negativo" "$(printf '%b' '**Caso de prueba (TestCase)**\n\n- **Requisito:** HU02-F2-CA6 (HU-02, Reserva de estadía)\n- **Tipo:** negativo\n- **Escenario automatizado:** `src/test/resources/features/reservas/reserva_estadia.feature`\n- **Tag para ejecutarlo:** `@Issue-10`\n\n**Resultado esperado:** La casilla de paseo queda deshabilitada y se ve la nota «El paseo solo está disponible para perros.»')"
crear "[TC-11] Tarifa por noche según tamaño (8, 12 y 30 kg)" "test-case,HU-02,Reserva de estadía,positivo" "$(printf '%b' '**Caso de prueba (TestCase)**\n\n- **Requisito:** HU02-F2-CA5 (HU-02, Reserva de estadía)\n- **Tipo:** positivo\n- **Escenario automatizado:** `src/test/resources/features/reservas/reserva_estadia.feature`\n- **Tag para ejecutarlo:** `@Issue-11`\n\n**Resultado esperado:** $40.000 / $55.000 / $70.000.')"
crear "[TC-12] Descuento 15% solo con más de 7 noches (7, 8 y 30 noches)" "test-case,HU-02,Reserva de estadía,positivo" "$(printf '%b' '**Caso de prueba (TestCase)**\n\n- **Requisito:** HU02-F2-CA4, HU02-F2-CA7 (HU-02, Reserva de estadía)\n- **Tipo:** positivo\n- **Escenario automatizado:** `src/test/resources/features/reservas/reserva_estadia.feature`\n- **Tag para ejecutarlo:** `@Issue-12`\n\n**Resultado esperado:** $385.000 / $374.000 / $1.402.500.')"
